/** Every persisted record has a numeric primary key generated by IndexedDB. */
export interface Entity {
  id: number;
}

/** Shape of a record before insertion: the key is assigned by the database. */
export type NewEntity<T extends Entity> = Omit<T, 'id'>;

/** Timestamps are stored as epoch milliseconds: indexable and JSON-safe for backups. */
export type EpochMs = number;
